mapper.select:
select SEQ_NO seqNo, FEE_TYPE feeType, SEC_ACCT_ID secAcctId, REGIST_ORG registOrg, PAY_CYCLE payCycle, PAY_DATE payDate, POSITION_START_DATE positionStartDate, POSITION_END_DATE positionEndDate, ACT_POSITION_END_DATE actPositionEndDate, FEE_AMT_TOTAL feeAmtTotal, DEAL_STATUS dealStatus from TRD_ACCOUNTMF_CONFIG
and SEC_ACCT_ID = #{secAcctId}
and DEAL_STATUS = #{dealStatus}
and POSITION_START_DATE >= #{positionStartDate}
and POSITION_END_DATE <= #{positionEndDate}

select SEC_ACCT_ID id, SEC_ACCT_NAME text from STL_SEC_ACCT_INFO where nvl(SEC_ACCT_TYPE,'XX') != #{secAcctType_fund}
and TRADE_PLACE = '01'
and ( SEC_ACCT_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and SEC_ACCT_ID = #{initValue}

select SEQ_NO,P_SEQ_NO,BOOKSET_ID,FEE_AMT_DETAIL,CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME
from TRD_ACCOUNTMF_CONFIGDETAIL


        and P_SEQ_NO = #{seqNo}


        and BOOKSET_ID = #{booksetId}
